entries[37304] = { ["name"] = "Feuerwasser des Apothekers", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Auf die Segel der \"Sündenbabel\" werfen, um sie in Brand zu setzen. Die Matrosen werden 2 Minuten lang beschäftigt sein - Zeit genug für Euch, um unter Deck zu gelangen und Euch um den Kapitän zu kümmern. (5 Sek. Abklingzeit)" }
